<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class StockUniformService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function item(mixed $id):array {$r=$this->row('stock_items','stock_id',$id);$this->access->requireSite($r['site_id']);return $r;}
    public function list(array $input,bool $self=false):array {
        $this->fields($input,$self?[]:['site_id']);if($self){$rows=$this->db->fetchAll('SELECT a.*,s.site_id,s.sku,s.item_name,s.item_size,s.category FROM stock_allocations a JOIN stock_items s ON s.company_id=a.company_id AND s.stock_id=a.stock_id WHERE a.company_id=:company AND a.employee_id=:employee ORDER BY allocation_id DESC LIMIT 300',['company'=>$this->company(),'employee'=>$this->employee()]);foreach($rows as&$r)unset($r['signature_base64']);unset($r);return array_values(array_filter($rows,fn($r)=>$this->access->allowed($r['site_id'])));}
        $s=$this->access->requireSite($input['site_id']??null);$rows=$this->db->fetchAll('SELECT * FROM stock_items WHERE company_id=:company AND site_id=:site ORDER BY sku,item_size LIMIT 300',['company'=>$this->company(),'site'=>$s['site_id']]);foreach($rows as&$r){$r['low_stock']=(int)$r['available_quantity']<=(int)$r['reorder_level'];$r['allocations']=$this->db->fetchAll('SELECT allocation_id,stock_id,employee_id,quantity,returned_quantity,written_off_quantity,due_at,state,revision,accepted_at,signature_sha256 FROM stock_allocations WHERE company_id=:company AND stock_id=:id ORDER BY allocation_id DESC LIMIT 200',['company'=>$this->company(),'id'=>$r['stock_id']]);$r['movements']=$this->db->fetchAll('SELECT movement_id,allocation_id,movement_type,quantity,affected_quantity,balance_after,notes,actor_user_id,occurred_at FROM stock_movements WHERE company_id=:company AND stock_id=:id ORDER BY movement_id DESC LIMIT 200',['company'=>$this->company(),'id'=>$r['stock_id']]);}unset($r);return $rows;
    }
    public function create(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','sku','item_name','item_size','category','reorder_level']);$s=$this->access->requireSite($input['site_id']??null);$sku=strtoupper($this->text($input['sku']??null,60));$size=strtoupper($this->text($input['item_size']??null,30));$category=$input['category']??null;if(!preg_match('/^[A-Z0-9_-]+$/D',$sku)||!in_array($category,['UNIFORM','PPE','CONSUMABLE','OTHER'],true))throw HttpException::unprocessable('Use a stock code and supported category.');if($this->db->fetch('SELECT stock_id FROM stock_items WHERE company_id=:company AND site_id=:site AND sku=:sku AND item_size=:size',['company'=>$this->company(),'site'=>$s['site_id'],'sku'=>$sku,'size'=>$size]))throw HttpException::conflict('Stock code/size already exists at this site.');$this->db->execute('INSERT INTO stock_items(company_id,site_id,sku,item_name,item_size,category,reorder_level) VALUES(:company,:site,:sku,:name,:size,:category,:reorder)',['company'=>$this->company(),'site'=>$s['site_id'],'sku'=>$sku,'name'=>$this->text($input['item_name']??null,150),'size'=>$size,'category'=>$category,'reorder'=>$this->number($input['reorder_level']??null,0,1000000)]);return $this->created('stock_item');});}
    public function movement(string $id,string $action,array $input):array {return $this->atomic(function()use($id,$action,$input){
        $this->fields($input,match($action){'receive','adjust'=>['operation_uuid','quantity','notes'],'issue'=>['operation_uuid','quantity','notes','employee_id','due_at'],'return','writeoff'=>['operation_uuid','quantity','notes','allocation_id','condition'],'cancel'=>['operation_uuid','notes','allocation_id'],default=>throw HttpException::notFound()});$item=$this->item($id);$uuid=$input['operation_uuid']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/Di',$uuid))throw HttpException::unprocessable('Use a stable operation UUID.');$canonical=$input;ksort($canonical);$hash=hash('sha256',json_encode([$id,$action,$this->actor(),$canonical],JSON_THROW_ON_ERROR));$prior=$this->db->fetch('SELECT request_hash,receipt_json FROM stock_movements WHERE company_id=:company AND operation_uuid=:uuid',['company'=>$this->company(),'uuid'=>$uuid]);if($prior){if(!hash_equals($prior['request_hash'],$hash))throw HttpException::conflict('Movement retry payload changed.');return json_decode($prior['receipt_json'],true,512,JSON_THROW_ON_ERROR);}
        $notes=$this->text($input['notes']??null,2000);$allocation=null;$delta=0;$quantity=$action==='cancel'?0:$this->number($input['quantity']??null,$action==='adjust'?0:1,1000000);$type=strtoupper($action);$state=null;
        if($action==='receive')$delta=$quantity;
        elseif($action==='adjust'){// A counted available balance, not a silent ledger edit.
            $quantity=$this->number($input['quantity']??null,0,1000000);$delta=$quantity-(int)$item['available_quantity'];
        }elseif($action==='issue'){$e=$this->row('employees','employee_id',$input['employee_id']??null);$due=$this->at($input['due_at']??null);if($e['employment_status']!=='ACTIVE'||$due<=gmdate('Y-m-d H:i:s')||strtotime($due.' UTC')>time()+366*86400)throw HttpException::unprocessable('Choose an active recipient and return deadline within a year.');if($quantity>(int)$item['available_quantity'])throw HttpException::conflict('Insufficient available stock.');$this->db->execute('INSERT INTO stock_allocations(company_id,stock_id,employee_id,quantity,due_at) VALUES(:company,:stock,:employee,:qty,:due)',['company'=>$this->company(),'stock'=>$id,'employee'=>$e['employee_id'],'qty'=>$quantity,'due'=>$due]);$allocation=(string)$this->db->connection()->lastInsertId();$delta=-$quantity;$state='PENDING_ACCEPTANCE';
        }else{$a=$this->row('stock_allocations','allocation_id',$input['allocation_id']??null);if((string)$a['stock_id']!==$id)throw HttpException::notFound();$allocation=(string)$a['allocation_id'];$outstanding=(int)$a['quantity']-(int)$a['returned_quantity']-(int)$a['written_off_quantity'];if($action==='cancel'){if($a['state']!=='PENDING_ACCEPTANCE')throw HttpException::conflict('Only unaccepted allocations can be cancelled.');$quantity=(int)$a['quantity'];$delta=$quantity;$state='CANCELLED';$this->db->execute("UPDATE stock_allocations SET state='CANCELLED',revision=revision+1 WHERE company_id=:company AND allocation_id=:id",['company'=>$this->company(),'id'=>$allocation]);}else{if(!in_array($a['state'],['ISSUED','PARTIAL'],true)||$quantity>$outstanding)throw HttpException::conflict('Return/write-off exceeds the accepted outstanding allocation.');$condition=$input['condition']??null;if($action==='return'&&!in_array($condition,['RESTOCK','QUARANTINE'],true))throw HttpException::unprocessable('Confirm restock or quarantine after physically checking the return.');if($action==='writeoff'&&$condition!=='LOST')throw HttpException::unprocessable('Confirm a lost/damaged write-off.');$state=$quantity===$outstanding?'SETTLED':'PARTIAL';$returned=(int)$a['returned_quantity']+($action==='return'?$quantity:0);$written=(int)$a['written_off_quantity']+($action==='writeoff'?$quantity:0);$delta=$action==='return'&&$condition==='RESTOCK'?$quantity:0;$type=$action==='return'?'RETURN_'.$condition:'WRITE_OFF';$this->db->execute('UPDATE stock_allocations SET returned_quantity=:returned,written_off_quantity=:written,state=:state,revision=revision+1 WHERE company_id=:company AND allocation_id=:id',['returned'=>$returned,'written'=>$written,'state'=>$state,'company'=>$this->company(),'id'=>$allocation]);}}
        $balance=(int)$item['available_quantity']+$delta;if($balance<0||$balance>1000000)throw HttpException::conflict('Available balance is outside its allowed range.');$this->db->execute('UPDATE stock_items SET available_quantity=:balance,revision=revision+1 WHERE company_id=:company AND stock_id=:id',['balance'=>$balance,'company'=>$this->company(),'id'=>$id]);$receipt=['stock_id'=>$id,'allocation_id'=>$allocation,'available_quantity'=>$balance,'state'=>$state,'operation_uuid'=>$uuid];$this->db->execute('INSERT INTO stock_movements(company_id,stock_id,allocation_id,operation_uuid,request_hash,movement_type,quantity,affected_quantity,balance_after,notes,actor_user_id,occurred_at,receipt_json) VALUES(:company,:stock,:allocation,:uuid,:hash,:type,:qty,:affected,:balance,:notes,:actor,:now,:receipt)',['company'=>$this->company(),'stock'=>$id,'allocation'=>$allocation,'uuid'=>$uuid,'hash'=>$hash,'type'=>$type,'qty'=>$delta,'affected'=>$quantity,'balance'=>$balance,'notes'=>$notes,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'receipt'=>json_encode($receipt,JSON_THROW_ON_ERROR)]);$this->audit->record('stock_movement',$action,$id,[],[],['allocation_id'=>$allocation,'quantity'=>$quantity,'balance_after'=>$balance]);return $receipt;
    });}
    public function accept(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','signature_base64']);$a=$this->row('stock_allocations','allocation_id',$id);if((string)$a['employee_id']!==$this->employee())throw HttpException::notFound();$this->item($a['stock_id']);if($this->row('employees','employee_id',$a['employee_id'])['employment_status']!=='ACTIVE')throw HttpException::forbidden('An active employee is required.');if($a['state']!=='PENDING_ACCEPTANCE'||$a['due_at']<=gmdate('Y-m-d H:i:s')||$this->number($input['expected_revision']??null)!==(int)$a['revision'])throw HttpException::conflict('Allocation changed or expired.');$sig=WorkflowMedia::image($input['signature_base64']??null,true);$this->db->execute("UPDATE stock_allocations SET state='ISSUED',revision=revision+1,accepted_at=:now,signature_base64=:signature,signature_sha256=:hash WHERE company_id=:company AND allocation_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'signature'=>$sig['base64'],'hash'=>$sig['sha256'],'company'=>$this->company(),'id'=>$id]);$this->audit->record('stock_allocation','recipient_accepted',$id);return ['accepted'=>true];});}
    public function receipt(string $id,bool $self=false):array {$a=$this->row('stock_allocations','allocation_id',$id);if($self&&(string)$a['employee_id']!==$this->employee())throw HttpException::notFound();$item=$this->item($a['stock_id']);if($a['signature_base64']){$bytes=base64_decode($a['signature_base64'],true);if($bytes===false||!hash_equals($a['signature_sha256'],hash('sha256',$bytes)))throw HttpException::conflict('Signature integrity check failed.');}$this->audit->record('stock_allocation','receipt_viewed',$id);return ['item'=>$item,'allocation'=>$a,'movements'=>$this->db->fetchAll('SELECT movement_type,quantity,affected_quantity,balance_after,notes,actor_user_id,occurred_at FROM stock_movements WHERE company_id=:company AND allocation_id=:id ORDER BY movement_id',['company'=>$this->company(),'id'=>$id])];}
}
